actions.script:
const fixed = ec.context.get('projectTabId') || null
const theMode = ['items', 'plan', 'portfolio'].includes(mode) ? mode : 'items'
const projectOptions = fixed ? [] : Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').call()?.projectList || [])
// in ProjectDetail's tab the project is its workEffortId even when the user may not see it (then "not available")
let project = fixed || rootWorkEffortId || (ec.context.get('inProjectDetail') ? workEffortId : null) || null
if (!project && theMode === 'items') {
    const mine = Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').parameters({memberOnly: true}).call()?.projectList || [])
    project = mine[0]?.key || projectOptions[0]?.key || null
    if (!project) { ec.web.sendJsonResponse({projectOptions: projectOptions, noProject: true}); return }
}
const out = ec.service.sync().name('ironstone.projects.PlanningServices.get#Timeline').parameters({mode: theMode, rootWorkEffortId: project,
    list: list || null, text: text || null, purposeEnumId: purposeEnumId || null, assigneePartyId: assigneePartyId || null, sprintId: sprintId || null,
    milestoneId: milestoneId || null, releaseId: releaseId || null, labelId: labelId || null, planList: planList || null,
    projectList: projectList || null}).call() || {}
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({projectOptions: projectOptions, notAvailable: true, rootWorkEffortId: project}); return }
if (out.timeline?.notAvailable) { ec.web.sendJsonResponse({projectOptions: projectOptions, notAvailable: true, rootWorkEffortId: project}); return }
ec.web.sendJsonResponse({timeline: out.timeline, projectOptions: projectOptions, projectFixed: !!fixed})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.move#TimelineItem').parameters({workEffortId: itemWorkEffortId || '',
    startDay: startDay ?? null, dueDay: dueDay ?? null, shiftDays: shiftDays || null, moveSubtree: moveSubtree === 'Y' || moveSubtree === 'true',
    autoSchedule: autoSchedule === 'Y' || autoSchedule === 'true'}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {movedCount: Array.from(out.movedList || []).length, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.save#TimelineDependency').parameters({workEffortId: dependentId || '',
    toWorkEffortId: predecessorId || '', lagDays: lagDays ?? null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {saved: true, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.remove#TimelineDependency').parameters({workEffortId: dependentId || '',
    toWorkEffortId: predecessorId || ''}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {removed: true, messageInfos: [{type: 'success', message: out.message}]})
